import {createInstructionGate} from './game-instructions.js';
import {prepareCanvas} from './touch-render.js';
import {drawBackdrop,drawFood,iconArt,coverArt} from './premium-art.js';
import {DB,player,save,commitRound,LEVELS} from './data.js';
import {audio,fx} from './audio.js';
import {CircuitBoard,CIRCUIT_LEVELS,WIRE_COLORS,WIRE_SIGNS,gridWalk,compareCircuit} from './circuit-core.js';
import {FaceModel,FOODS,FACE_MODES,compareFeed} from './face-core.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seconds=t=>(t/1000).toFixed(1)+'s';
let faceImages;
async function preloadFaces(){if(!faceImages)faceImages=Promise.all(['closed','open'].map(name=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>{faceImages=null;reject(Error('The character images could not load. Reconnect and try again.'));};i.src='assets/face-'+name+'.png';})));return faceImages;}
export function openNewArcade(host,{kind='circuit',exit,notify,ask,initialPage='setup'}){
 const face=kind==='face',name=face?'Feed the Face':'Circuit Rush',game=face?'face':'circuit',$=s=>host.querySelector(s);
 let disposed=false,page='',paused=false,difficulty=3,level=13,ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],versus=false,mode=face?'classic':'speed',series=1,round=0,wins=[0,0],models=[],raf=0,last=0,clock=0,images=[],loadFailed=false,phase='setup',recorded=false,rounds=[],seed=0,boardLevel=[],marathon=[],personalBest=false;
 let imageTask=face?preloadFaces().then(v=>{images=v;}).catch(e=>{loadFailed=true;notify(e.message,'error');}):Promise.resolve();
 host.innerHTML=`<section class="new-arcade ${face?'face-room':'circuit-room'}"><header class="new-header"><button class="btn secondary" id="newExit">⌂ BACK TO ARCADE</button><div><span class="eyebrow">${face?'A LITTLE SECRET. A BIG APPETITE.':'NEON ARCADE UNIVERSE'}</span><h1>${face?'🍕':'⚡'} ${name}</h1></div><nav><button class="btn secondary" id="newSetup">SETUP</button><button class="btn secondary" id="newRecords">♛ RECORDS</button><button class="icon-btn" id="newMute" aria-label="Mute sound">♪</button><button class="icon-btn" id="newFull" aria-label="Fullscreen">⛶</button></nav></header><div id="newContent"></div></section>`;
 const content=$('#newContent');
 $('#newExit').onclick=exit;$('#newFull').onclick=()=>document.getElementById('fullscreen').click();$('#newMute').onclick=()=>{document.getElementById('mute').click();$('#newMute').textContent=DB.settings.muted?'♪̸':'♪';};
 async function goSetup(){if(page==='play'&&phase==='play'){paused=true;if(!await ask('Leave this challenge?','Unfinished rounds will not create a score.')){paused=false;return;}}setup();}
 $('#newSetup').onclick=goSetup;$('#newRecords').onclick=async()=>{if(page==='play'&&phase==='play'){paused=true;if(!await ask('Open records?','Unfinished rounds will not create a score.')){paused=false;return;}}records();};
 function options(selected){return DB.profiles.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');}
 const gate=createInstructionGate({game:game,onBack:exit,onReview:()=>pause(true)});
 function requestSession(){gate.show({players:(versus?ids:ids.slice(0,1)).map(id=>player(id).name),difficulty:LEVELS[difficulty-1],mode,modeLabel:face?FACE_MODES[mode]:{speed:'Speed Race',accuracy:'Accuracy Battle',marathon:'Circuit Marathon'}[mode]},()=>{audio();startRound(true);});}
 function setup(){page='setup';phase='setup';paused=false;models=[];content.innerHTML=`<div class="new-setup"><section class="new-intro"><span class="eyebrow">${face?'YOU FOUND IT!':'CONNECT. THINK. GLOW.'}</span><h2>${face?'Big face.<br><em>Bigger appetite.</em>':'Bring the board<br><em>to life.</em>'}</h2><div class="new-intro-art ${face?'discovery':''}">${face?'<img src="assets/face-closed.png" alt="The hungry floating face">':coverArt('circuit')}</div><p>${face?'Choose the food the face requests, then tap ahead of its glowing mouth to shoot. Requests are checked at launch, so food already flying stays fair.':'Drag from a solid lettered source to the matching ring. Wires cannot cross except at a bridge. Plan ahead, use Undo, and power every circuit.'}</p><p class="tiny">${face?'Classic: 60 seconds · Target: feed 7, then advance · Survival: six misses allowed, speed rises · Frenzy: fast shots and combos.':'Levels 1–6: Easy · 7–12: Normal · 13–18: Hard · 19–24: Very Hard · 25–30: Expert. Each board has a verified solution.'}</p></section><section class="panel new-options"><div class="mode-toggle"><button data-count="1" class="${!versus?'selected':''}">☺ 1 Player</button><button data-count="2" class="${versus?'selected':''}" ${DB.profiles.length<2?'disabled':''}>⚔ 2 Players</button></div><div class="form-columns"><label>Player 1<select id="newP1">${options(ids[0])}</select></label>${versus?`<label>Player 2<select id="newP2">${options(ids[1])}</select></label>`:''}</div><label>${face?'Game mode':'Circuit Battle mode'}<select id="newMode">${Object.entries(face?FACE_MODES:{speed:'Speed Race',accuracy:'Accuracy Battle',marathon:'Circuit Marathon'}).map(([id,label])=>`<option value="${id}" ${mode===id?'selected':''}>${label}</option>`).join('')}</select></label>${versus?`<label>Match length<select id="newSeries">${(face?[1,3,5]:[1,5]).map(n=>`<option value="${n}" ${series===n?'selected':''}>${n===1?'Single round':'Best of '+n}</option>`).join('')}</select></label>`:''}<label>DIFFICULTY <b id="newDiffName">${LEVELS[difficulty-1]}</b><input id="newDifficulty" type="range" min="1" max="5" step="1" value="${difficulty}" aria-label="Difficulty"></label>${!face?`<button class="btn secondary" id="newLevels">▦ LEVEL ${level} · ${CIRCUIT_LEVELS[level-1].name}</button>`:''}<p class="new-rules">${face?['Large target · slow, predictable movement','Medium target · gentle turns','Precise mouth shots · unpredictable movement','Fast head · moving barrier','Small mouth · two moving barriers'][difficulty-1]:'Sources A–F power in order on Expert. Tap switches and rotators before drawing through them. Moving gates latch completed wires.'}</p><div class="intro-fairness">${versus?face?'Independent selections · simultaneous shots · points, then accuracy':'Independent boards · identical puzzles · separate touch tracking':face?'Your records stay inside this secret game.':'All 30 boards available · mistakes and time determine your score.'}</div><button class="btn primary full" id="newLaunch">${versus?'START THE MATCH ⚔':'LET’S PLAY →'}</button></section></div>`;
 content.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{versus=b.dataset.count==='2';setup();});$('#newP1').onchange=e=>ids[0]=e.target.value;if($('#newP2'))$('#newP2').onchange=e=>ids[1]=e.target.value;$('#newMode').onchange=e=>mode=e.target.value;if($('#newSeries'))$('#newSeries').onchange=e=>series=+e.target.value;
 $('#newDifficulty').oninput=e=>{difficulty=+e.target.value;level=(difficulty-1)*6+1;$('#newDiffName').textContent=LEVELS[difficulty-1];};$('#newDifficulty').onchange=setup;
 if(!face)$('#newLevels').onclick=levelSelect;
 $('#newLaunch').onclick=async()=>{ids[0]=$('#newP1').value;if(versus)ids[1]=$('#newP2').value;if(versus&&ids[0]===ids[1]){notify('Choose two different players.');return;}await imageTask;if(disposed)return;if(face&&(!images.length||loadFailed)){notify('Character images are unavailable. Please reconnect and reload.','error');return;}DB.active=ids[0];save();round=0;wins=[0,0];rounds=[];requestSession();};
 }
 function levelSelect(){page='levels';phase='setup';content.innerHTML=`<div class="new-levels"><div class="page-heading"><div><span class="eyebrow">30 CIRCUIT CHALLENGES</span><h2>Choose your frequency.</h2><p>Every board is playable. Completed boards show your best stars and time.</p></div><button class="btn secondary" id="levelBack">← SETUP</button></div>${LEVELS.map((d,i)=>`<section><h3>${d}</h3><div class="circuit-level-grid">${CIRCUIT_LEVELS.slice(i*6,i*6+6).map(l=>{const best=player(ids[0]).results.filter(r=>r.game==='circuit'&&r.levelId==='level-'+l.id&&r.mode==='solo'&&r.details?.completed).sort((a,b)=>b.score-a.score)[0];return `<button data-level="${l.id}" class="${level===l.id?'selected':''}"><b>${l.id}</b><span>${l.name}</span><small>${best?'★'.repeat(best.stars||1)+' · '+seconds(best.duration*1000):l.n+' × '+l.n+' · '+l.pairs.length+' circuits'}</small></button>`;}).join('')}</div></section>`).join('')}</div>`;$('#levelBack').onclick=setup;content.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;difficulty=CIRCUIT_LEVELS[level-1].tier;setup();});}
 function startRound(acknowledged=false){round++;seed=Date.now()>>>0;clock=0;paused=false;recorded=false;personalBest=false;phase='play';page='play';boardLevel=[level,level];marathon=[{boards:0,points:0,errors:0,connections:0},{boards:0,points:0,errors:0,connections:0}];models=face?[new FaceModel({difficulty,mode,players:versus?2:1,seed,level:targetLevel})]:(versus?ids:ids.slice(0,1)).map(()=>new CircuitBoard(CIRCUIT_LEVELS[level-1],difficulty));buildPlay();last=performance.now();}
 let targetLevel=1;
 function buildPlay(){content.innerHTML=`<div class="new-play"><div class="new-matchbar"><span>${LEVELS[difficulty-1]} · ${face?FACE_MODES[mode]:'LEVEL '+level+' · '+CIRCUIT_LEVELS[level-1].name}${versus&&series>1?' · ROUND '+round+' · '+wins.join(' : '):''}</span><div><button class="btn secondary" id="newPause">Ⅱ PAUSE</button><button class="btn secondary" id="newRestart">↻ RESTART</button></div></div><div class="new-playfield ${!face&&versus?'circuit-split':''}">${face?`<section class="new-zone face-zone"><div class="new-hud" id="faceHud"></div><div class="new-canvas-wrap"><canvas id="faceCanvas" aria-label="Feed the Face: tap ahead of the moving mouth to shoot"></canvas></div><div class="face-request" id="faceRequest"></div><div class="face-trays">${(versus?ids:ids.slice(0,1)).map((id,owner)=>`<div class="food-tray" aria-label="${esc(player(id).name)} food selection">${FOODS.map((f,i)=>`<button data-food="${i}" data-food-owner="${owner}" aria-label="${esc(player(id).name)} ${f.name}" class="${i===models[0].selectedFoods[owner]?'selected':''}">${iconArt('food',f.name)}<small>${f.name}</small></button>`).join('')}</div>`).join('')}</div><div class="new-help" id="faceHelp">Choose the requested food, then TAP ${versus?'your side':'the playfield'} to shoot. Anticipate the moving mouth.</div></section>`:models.map((m,i)=>`<section class="new-zone" style="--player:${player(ids[i]).color}" data-board="${i}"><div class="new-hud" data-hud="${i}"></div><div class="new-canvas-wrap"><canvas data-circuit="${i}" aria-label="${esc(player(ids[i]).name)} circuit board"></canvas></div><div class="circuit-tools"><button class="btn secondary" data-undo="${i}">↶ UNDO</button><button class="btn secondary" data-reset="${i}">RESET</button><span data-clock="${i}"></span></div><div class="new-help" data-help="${i}"></div></section>`).join('')}</div><div class="new-overlay" id="newOverlay" hidden></div></div>`;
 $('#newPause').onclick=()=>pause(!paused);$('#newRestart').onclick=async()=>{pause(true);if(await ask('Restart the match?','Current unfinished progress will be discarded. Completed match records stay saved.')){round=0;wins=[0,0];rounds=[];startRound();}else pause(false);};
 if(face){content.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>{if(phase!=='play'||paused)return;const owner=+b.dataset.foodOwner;models[0].selectFood(owner,+b.dataset.food);content.querySelectorAll('[data-food-owner="'+owner+'"]').forEach(x=>x.classList.toggle('selected',x===b));});bindFace($('#faceCanvas'));}
 else{content.querySelectorAll('[data-circuit]').forEach(c=>bindCircuit(c,+c.dataset.circuit));content.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{if(!paused&&phase==='play')models[+b.dataset.undo].undo();});content.querySelectorAll('[data-reset]').forEach(b=>b.onclick=async()=>{const i=+b.dataset.reset;pause(true);if(await ask('Reset this board?','Erase its wires. The timer and mistakes will keep counting.'))models[i].reset();pause(false);});}
 resize();observer.disconnect();content.querySelectorAll('canvas').forEach(c=>observer.observe(c));
 }
 const observer=new ResizeObserver(()=>resize());
 function resize(){content.querySelectorAll('canvas').forEach(c=>{const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(r.width&&r.height){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}});}
 function boardGeometry(c,m){const r=c.getBoundingClientRect(),size=Math.min(r.width-24,r.height-24),unit=size/m.n;return{r,size,unit,x:(r.width-size)/2,y:(r.height-size)/2};}
 function cellAt(c,m,e){const g=boardGeometry(c,m),x=e.clientX-g.r.left-g.x,y=e.clientY-g.r.top-g.y;if(x<0||y<0||x>=g.size||y>=g.size)return null;return Math.floor(y/g.unit)*m.n+Math.floor(x/g.unit);}
 function bindCircuit(c,i){let pointer=null;const up=e=>{if(pointer!==e.pointerId)return;if(phase==='play'&&!paused)models[i].end(e.pointerId);pointer=null;if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);};
 c.onpointerdown=e=>{if(paused||phase!=='play'||pointer!==null)return;e.preventDefault();const m=models[i],cell=cellAt(c,m,e);if(cell==null||m.done)return;
 const component=m.level.components.find(x=>x.cell===cell&&['switch','rotator'].includes(x.kind));if(component){m.component(cell);fx('tap');return;}
 if(m.start(cell,e.pointerId)){pointer=e.pointerId;c.setPointerCapture(e.pointerId);fx('tap');}};
 c.onpointermove=e=>{if(pointer!==e.pointerId||paused||phase!=='play')return;e.preventDefault();const m=models[i],cell=cellAt(c,m,e);if(cell==null||!m.active)return;const a=m.active,path=m.paths[a.pair],last=path.at(-1);for(const next of gridWalk(last,cell,m.n)){if(!m.move(next,e.pointerId))break;if(!m.active){fx('hit');break;}}};
 c.onpointerup=up;c.onpointercancel=up;c.onlostpointercapture=up;
 }
 function facePoint(c,e){const r=c.getBoundingClientRect(),scale=Math.min(r.width/1000,r.height/640),x=(e.clientX-r.left-(r.width-scale*1000)/2)/scale,y=(e.clientY-r.top-(r.height-scale*640)/2)/scale;return x<0||x>1000||y<0||y>640?null:{x,y};}
 function bindFace(c){c.onpointerdown=e=>{if(paused||phase!=='play')return;e.preventDefault();const p=facePoint(c,e);if(!p)return;const owner=versus&&p.x>=500?1:0;if(models[0].shoot(owner,p.x,p.y))fx('launch-food');};}
 function cancelPointers(){if(face){for(const id of models[0]?.aims?.keys()||[])models[0].release(id,true);}else models.forEach(m=>m.cancel());}
 function pause(v){if(page!=='play'||phase!=='play')return;paused=v;cancelPointers();const o=$('#newOverlay');o.hidden=!v;$('#newPause').textContent=v?'▶ RESUME':'Ⅱ PAUSE';if(v){o.innerHTML='<div class="result-card"><span class="eyebrow">TAKE YOUR TIME</span><h2>Power paused.</h2><p>The clock, movement and animations are paused.</p><button class="btn primary" id="resumeNew">▶ RESUME</button></div>';$('#resumeNew').onclick=()=>pause(false);}last=performance.now();}
 function visibility(){if(document.hidden)pause(true);}document.addEventListener('visibilitychange',visibility);window.addEventListener('blur',visibility);
 function tick(t){if(disposed)return;const dt=Math.min(100,Math.max(0,t-last));last=t;if(page==='play'){
 if(phase==='play'&&!paused){clock+=dt;if(face){models[0].update(dt);for(const e of models[0].events.splice(0))fx(e.kind==='feed'?'hit':e.kind);if(models[0].done)endRound();}else{
 models.forEach((m,i)=>{m.update(dt);if(m.done&&mode==='marathon'){marathon[i].boards++;marathon[i].points+=m.score;marathon[i].errors+=m.errors;marathon[i].connections+=m.connected.size;boardLevel[i]=(difficulty-1)*6+((boardLevel[i]-(difficulty-1)*6)%6)+1;models[i]=new CircuitBoard(CIRCUIT_LEVELS[boardLevel[i]-1],difficulty);fx('go');}});
 if(mode!=='marathon'&&models.every(m=>m.done)||clock>=(mode==='marathon'?180000:mode==='accuracy'?120000:180000))endRound();
 }}
 if(face){const c=$('#faceCanvas');if(c){renderFace(c,models[0],images,ids,versus);if($('#faceRequest').dataset.food!==String(models[0].request)){$('#faceRequest').dataset.food=String(models[0].request);$('#faceRequest').innerHTML=iconArt('food',FOODS[models[0].request].name)+'<span>I WANT '+FOODS[models[0].request].name.toUpperCase()+'!</span>';}$('#faceHud').innerHTML=models[0].stats.map((s,i)=>`<span style="--player:${player(ids[i]).color}">${player(ids[i]).avatar} ${esc(player(ids[i]).name)} <b>${s.score}</b><small>${s.hits} feeds / ${s.shots} shots · ${models[0].accuracy(i)}% · combo ×${Math.min(5,1+Math.floor(Math.max(0,s.streak-1)/3))}</small></span>`).join('')+`<strong>${Math.max(0,Math.ceil((models[0].duration-models[0].clock)/1000))}s${mode==='survival'&&!versus?' · ♥ '+models[0].lives:mode==='target'?' · '+models[0].hits+'/'+models[0].target:''}</strong>`;}}
 else models.forEach((m,i)=>{const c=$(`[data-circuit="${i}"]`);if(c){renderCircuit(c,m,boardGeometry(c,m));$(`[data-hud="${i}"]`).innerHTML=`<span>${player(ids[i]).avatar} ${esc(player(ids[i]).name)}<small>${m.connected.size}/${m.level.pairs.length} powered${mode==='marathon'?' · '+marathon[i].boards+' boards':''}</small></span><strong>${m.score+(marathon[i]?.points||0)}</strong>`;$(`[data-clock="${i}"]`).textContent=seconds(m.clock)+' · '+m.accuracy+'%';$(`[data-help="${i}"]`).textContent=m.feedback;}});
 }raf=requestAnimationFrame(tick);}
 function outcome(i){if(face){const m=models[0],s=m.stats[i];return{id:ids[i],score:Math.round(s.score),hits:s.hits,errors:s.misses,misses:s.misses,accuracy:m.accuracy(i),duration:m.clock/1000,soloWin:mode==='target'?m.hits>=m.target:s.hits>0,details:{successfulFeeds:s.hits,shots:s.shots,bestStreak:s.bestStreak,fastestShot:s.fastest,level:targetLevel,completed:mode==='target'&&m.hits>=m.target,mode,round}};}
 const m=models[i],mar=marathon[i];return{id:ids[i],score:m.score+mar.points,hits:m.connected.size+mar.connections,errors:m.errors+mar.errors,accuracy:Math.round(100*(m.connected.size+mar.connections)/Math.max(1,m.connected.size+mar.connections+m.errors+mar.errors)),duration:(mode==='marathon'?clock:m.clock)/1000,soloWin:m.done||mar.boards>0,stars:m.done?(m.errors===0?3:m.errors<=3?2:1):0,details:{completed:m.done||mar.boards>0,connections:m.connected.size+mar.connections,boards:mar.boards,mode,round}};}
 function endRound(){if(phase!=='play')return;phase='between';cancelPointers();const entries=(versus?ids:ids.slice(0,1)).map((_,i)=>outcome(i));let cmp=0;
 if(versus){if(face)cmp=compareFeed(models[0]);else if(mode==='marathon')cmp=marathon[0].boards-marathon[1].boards||models[0].connected.size-models[1].connected.size||entries[0].score-entries[1].score;else cmp=compareCircuit(models[0],models[1],mode);if(cmp)wins[cmp>0?0:1]++;}
 rounds.push(entries);const need=Math.ceil(series/2),finished=!versus||wins.some(w=>w>=need)||round>=series;
 if(finished)finishMatch();else showResults(entries,cmp,false);
 }
 function finishMatch(){if(recorded)return;recorded=true;phase='results';const entries=(versus?ids:ids.slice(0,1)).map((id,i)=>{const r=rounds.map(round=>round[i]),a=r.at(-1);return{...a,score:Math.round(r.reduce((s,x)=>s+x.score,0)/r.length),hits:r.reduce((s,x)=>s+x.hits,0),errors:r.reduce((s,x)=>s+x.errors,0),duration:r.reduce((s,x)=>s+x.duration,0),accuracy:face?Math.round(100*r.reduce((s,x)=>s+x.hits,0)/Math.max(1,r.reduce((s,x)=>s+x.details.shots,0))):Math.round(100*r.reduce((s,x)=>s+x.hits,0)/Math.max(1,r.reduce((s,x)=>s+x.hits+x.errors,0))),details:{...a.details,rounds:r.map(x=>x.details),roundWins:wins[i],series:versus?series:1}};});const cmp=versus?wins[0]-wins[1]:0,winnerId=versus?(cmp===0?null:ids[cmp>0?0:1]):undefined;
 // Secret badges are quiet and only rendered inside this game.
 const savedRecords=commitRound(entries,{game,difficulty,learn:false,mode:versus?'versus':'solo',seed,ruleset:face?'feeding-v2':'circuit-v1',levelId:face?mode+'-'+targetLevel:mode==='marathon'?'marathon-'+level: 'level-'+level,competition:mode,challengeKey:'series-'+(versus?series:1),winnerId});
 personalBest=savedRecords.some(r=>r.pb);
 if(face){entries.forEach((a,i)=>{const p=player(ids[i]),r=rounds.map(x=>x[i]),ds=r.flatMap(x=>x.details);const award=id=>{if(!p.achievements.some(a=>a.id===id))p.achievements.push({id,at:Date.now()});};if(a.hits)award('face-first');if(mode==='frenzy'&&a.hits>=10)award('face-frenzy');if(a.hits>=5&&a.accuracy===100)award('face-aim');if(winnerId===p.id)award('face-champion');if(p.results.filter(r=>r.game==='face').reduce((s,r)=>s+r.hits,0)>=100)award('face-master');if(ds.some(d=>d.bestStreak>=10))award('face-combo');});save();}
 fx('win');showResults(entries,cmp,true);
 }
 function showResults(entries,cmp,finished){const o=$('#newOverlay');o.hidden=false;o.innerHTML=`<div class="result-card wide new-celebration"><div class="eyebrow">${finished?personalBest?'✦ NEW PERSONAL BEST ✦':'RECORDS SAVED':'ROUND '+round+' COMPLETE'}</div><h2>${versus?(cmp===0?'A brilliant tie!':esc(player(ids[cmp>0?0:1]).name)+' wins'+(finished?'!':' the round!')):face?entries[0].soloWin?'Delicious work!':'Keep aiming!':entries[0].details.completed?'Circuit complete!':'Keep the sparks flying!'}</h2>${versus?'<p>Match score '+wins.join(' : ')+'</p>':''}<div class="results-grid">${entries.map((a,i)=>`<section><span class="avatar" style="--player:${player(ids[i]).color}">${player(ids[i]).avatar}</span><h3>${esc(player(ids[i]).name)}</h3><div class="big-score">${a.score}<small>${series>1&&versus?'AVERAGE SCORE / ROUND':'POINTS'}</small></div><p>${face?a.hits+' successful feeds':a.hits+' connections'} · ${a.accuracy}% accuracy<br>${seconds(a.duration*1000)} active time · ${a.errors} ${face?'misses':'mistakes'}${face?'<br>Best streak '+a.details.bestStreak+' · fastest flight '+(a.details.fastestShot==null?'—':seconds(a.details.fastestShot)):''}</p></section>`).join('')}</div><div class="modal-actions"><button class="btn secondary" id="resultHome">BACK TO ARCADE</button><button class="btn secondary" id="resultSetup">SETUP</button>${finished?`<button class="btn secondary" id="resultRecords">RECORDS</button>${!versus&&(!face&&models[0].done&&level<30||face&&mode==='target'&&entries[0].soloWin)?'<button class="btn accent" id="nextLevel">NEXT LEVEL →</button>':''}<button class="btn primary" id="newRematch">${versus?'REMATCH':'PLAY AGAIN'} ↻</button>`:'<button class="btn primary" id="nextRound">NEXT ROUND →</button>'}</div></div>`;
 $('#resultHome').onclick=exit;$('#resultSetup').onclick=setup;if(finished){$('#resultRecords').onclick=records;$('#newRematch').onclick=()=>{round=0;wins=[0,0];rounds=[];requestSession();};if($('#nextLevel'))$('#nextLevel').onclick=()=>{if(face)targetLevel++;else{level++;difficulty=CIRCUIT_LEVELS[level-1].tier;}round=0;rounds=[];requestSession();};}else $('#nextRound').onclick=startRound;
 }
 function records(){page='records';phase='setup';models=[];const rows=DB.profiles.flatMap(p=>p.results.filter(r=>r.game===game&&r.difficulty===difficulty&&r.mode===(versus?'versus':'solo')&&r.competition===mode).map(r=>({p,r}))).sort((a,b)=>b.r.score-a.r.score||a.r.duration-b.r.duration);content.innerHTML=`<div class="new-records"><div class="page-heading"><div><span class="eyebrow">${face?'JUST BETWEEN US':'CIRCUIT HALL OF FAME'}</span><h2>${name} records.</h2><p>${LEVELS[difficulty-1]} · ${face?FACE_MODES[mode]:mode} · ${versus?'2 players':'solo'}. Records remain separated by level and match length.</p></div><button class="btn primary" id="recordsPlay">PLAY →</button></div>${face?faceSummary(player()):''}${rows.length?`<div class="table-wrap"><table><thead><tr><th>PLAYER</th><th>CHALLENGE</th><th>SCORE</th><th>${face?'FEEDS':'CONNECTIONS'}</th><th>ACCURACY</th><th>TIME</th></tr></thead><tbody>${rows.map(({p,r})=>`<tr><td>${p.avatar} ${esc(p.name)}</td><td>${esc(r.levelId)} · ${r.details.series===1?'single':'best of '+r.details.series}</td><td>${r.score}</td><td>${r.hits}</td><td>${r.accuracy}%</td><td>${r.duration.toFixed(1)}s</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h2>Your first record awaits.</h2><p>Complete a round to save a real result.</p></div>'}${face?`<div class="trophy-grid">${SECRET_BADGES.map(b=>`<article class="trophy-card ${player().achievements.some(a=>a.id===b.id)?'unlocked':'locked'}"><span class="trophy-art">${b.icon}</span><h3>${b.name}</h3><p>${b.desc}</p></article>`).join('')}</div>`:''}</div>`;$('#recordsPlay').onclick=setup;}
 if(initialPage==='records')records();else setup();raf=requestAnimationFrame(tick);
 return()=>{disposed=true;gate.dispose();cancelAnimationFrame(raf);observer.disconnect();cancelPointers();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('blur',visibility);};
}
export const SECRET_BADGES=[{id:'face-first',name:'First Bite',icon:'🍕',desc:'Successfully feed the face.'},{id:'face-frenzy',name:'Food Frenzy',icon:'🌪️',desc:'Feed ten foods in a Frenzy round.'},{id:'face-aim',name:'Perfect Aim',icon:'🎯',desc:'Finish with at least five feeds and 100% accuracy.'},{id:'face-champion',name:'Hungry Champion',icon:'👑',desc:'Win a head-to-head match.'},{id:'face-master',name:'Feeding Master',icon:'🍽️',desc:'Reach 100 lifetime feeds.'},{id:'face-combo',name:'Combo King',icon:'🔥',desc:'Land ten successful shots in a row.'}];
function renderCircuit(c,m,g){const ctx=c.getContext('2d'),r=g.r;ctx.setTransform(c.width/r.width,0,0,c.height/r.height,0,0);ctx.fillStyle='#0d1c2c';ctx.fillRect(0,0,r.width,r.height);const u=g.unit,pt=cell=>({x:g.x+(cell%m.n+.5)*u,y:g.y+(Math.floor(cell/m.n)+.5)*u});
 ctx.lineWidth=1;for(let i=0;i<m.n*m.n;i++){const p=pt(i);ctx.fillStyle=m.level.walls.includes(i)?'#35415b':'#152c3b';ctx.strokeStyle='#375567';ctx.beginPath();ctx.roundRect(p.x-u*.46,p.y-u*.46,u*.92,u*.92,u*.1);ctx.fill();ctx.stroke();ctx.strokeStyle='#a2d6cc22';ctx.lineWidth=1;ctx.strokeRect(p.x-u*.38,p.y-u*.38,u*.76,u*.76);for(const sign of [-1,1]){ctx.fillStyle='#799ba955';ctx.fillRect(p.x+sign*u*.35-u*.025,p.y-u*.34,u*.05,u*.05);}if(m.level.walls.includes(i)){ctx.fillStyle='#8592ac';ctx.font=`${u*.36}px Arial`;ctx.textAlign='center';ctx.fillText('✕',p.x,p.y+u*.12);}}
 for(const cell of m.level.bridges){const p=pt(cell);ctx.strokeStyle='#d8e6ff';ctx.lineWidth=3;ctx.strokeRect(p.x-u*.33,p.y-u*.33,u*.66,u*.66);ctx.font=`${u*.23}px Arial`;ctx.textAlign='center';ctx.fillStyle='#b8d3ee';ctx.fillText('╬',p.x,p.y+u*.08);}
 for(const comp of m.level.components){const p=pt(comp.cell);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${u*.3}px Arial`;ctx.fillStyle=comp.kind==='booster'?'#ffd45f':comp.kind==='rotator'?'#aa96ff':m.gateOpen(comp)?'#67efba':'#ff87a9';if(comp.kind==='barrier'){const open=m.gateOpen(comp);ctx.save();ctx.globalAlpha=open?.3:.85;ctx.fillStyle=open?'#4bcaa6':'#ff87a9';ctx.fillRect(p.x-u*.35,p.y+(open?-u*.35:Math.sin(m.clock/170)*u*.08)-u*.07,u*.7,u*.14);ctx.restore();}ctx.fillText(comp.kind==='booster'?'⚡':comp.kind==='switch'?comp.open?'ON':'OFF':comp.kind==='rotator'?comp.axis==='h'?'↔':'↕':m.gateOpen(comp)?'GO':'WAIT',p.x,p.y+(comp.kind==='barrier'?u*.25:0));}
 for(const [id,path]of Object.entries(m.paths)){ctx.strokeStyle=WIRE_COLORS[+id];ctx.lineWidth=u*.13;ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowBlur=9;ctx.shadowColor=WIRE_COLORS[+id];ctx.beginPath();path.forEach((cell,k)=>{const p=pt(cell);if(k)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);});ctx.stroke();ctx.shadowBlur=0;if(m.connected.has(+id)&&path.length){const p=pt(path[Math.floor(m.clock/110)%path.length]);ctx.fillStyle='white';ctx.beginPath();ctx.arc(p.x,p.y,u*.06,0,Math.PI*2);ctx.fill();}}
 for(const p of m.level.pairs){for(const [j,cell]of [p.source,p.target].entries()){const q=pt(cell);ctx.fillStyle=j?'#11283d':WIRE_COLORS[p.id];ctx.strokeStyle=WIRE_COLORS[p.id];ctx.lineWidth=u*.045;ctx.beginPath();ctx.arc(q.x,q.y,u*.29,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${u*.28}px Arial`;ctx.fillStyle=j?WIRE_COLORS[p.id]:'#102334';ctx.fillText(WIRE_SIGNS[p.id]+(p.timed?'⌛':''),q.x,q.y);}}
 if(m.active?.deadline<Infinity){const a=pt(m.paths[m.active.pair].at(-1));ctx.fillStyle='white';ctx.font=`bold ${Math.max(12,u*.22)}px Arial`;ctx.fillText(Math.max(0,(m.active.deadline-m.clock)/1000).toFixed(1),a.x,a.y-u*.35);}if(m.flash){ctx.fillStyle='#ff456515';ctx.fillRect(0,0,r.width,r.height);}
}
function renderFace(c,m,images,ids,versus){const {c:x}=prepareCanvas(c);const bg=x.createLinearGradient(0,0,1000,640);bg.addColorStop(0,'#162240');bg.addColorStop(1,'#3c214b');x.fillStyle=bg;x.fillRect(0,0,1000,640);drawBackdrop(x,'candy food arcade',m.clock);
 for(let i=0;i<30;i++){const px=(i*173+Math.sin(m.clock/2500+i)*15)%1000,py=(i*97)%640;x.fillStyle=i%2?'#ab91fb45':'#73eddb35';x.beginPath();x.arc(px,py,2+i%3,0,Math.PI*2);x.fill();}
 for(const o of m.obstacles){x.fillStyle='#ff7aaba0';x.shadowColor='#ff75a7';x.shadowBlur=12;x.fillRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h);x.shadowBlur=0;}
 const h=m.head,img=images[m.expression==='open'?1:0];if(img){x.save();x.shadowBlur=28;x.shadowColor='#a88cff55';// Fixed character viewport. Expression images share mouth/eye anchors, no layout reflow.
 const imageWidth=h.h*img.naturalWidth/img.naturalHeight;x.drawImage(img,h.x-imageWidth/2,h.y-h.h/2,imageWidth,h.h);x.restore();}
 if(m.clock<m.angryUntil){x.save();x.translate(h.x,h.y-h.h*.15);x.strokeStyle='#302034';x.lineWidth=7;x.lineCap='round';for(const side of [-1,1]){x.beginPath();x.moveTo(side*h.w*.13,-2);x.lineTo(side*h.w*.32,-14);x.stroke();}x.restore();x.font='bold 18px Outfit';x.fillStyle='#ffadbd';x.textAlign='center';x.fillText('That was not my order!',h.x,h.y-h.h/2-16);}
 const mouth=m.mouth;x.strokeStyle='#ffd668a0';x.lineWidth=2;x.setLineDash([3,5]);x.beginPath();x.ellipse(mouth.x,mouth.y,mouth.rx,mouth.ry,0,0,Math.PI*2);x.stroke();x.setLineDash([]);
 m.launchers.forEach((l,i)=>{const color=player(ids[i]).color;x.fillStyle=color+'30';x.strokeStyle=color;x.lineWidth=3;x.beginPath();x.arc(l.x,l.y,65,0,Math.PI*2);x.fill();x.stroke();x.font='bold 18px Outfit, Arial';x.fillStyle=color;x.textAlign='center';x.fillText('P'+(i+1)+' · TAP TO SHOOT',l.x,l.y+64);drawFood(x,FOODS[m.selectedFoods[i]].name.toLowerCase(),l.x,l.y,.72);});
 for(const p of m.projectiles){x.save();x.translate(p.x,p.y);x.rotate((m.clock-p.born)/220);x.shadowBlur=14;x.shadowColor=player(ids[p.owner]).color;x.fillStyle=player(ids[p.owner]).color;x.beginPath();x.arc(0,0,20,0,Math.PI*2);x.fill();drawFood(x,FOODS[p.food].name.toLowerCase(),0,0,.46);x.restore();}
 for(const pop of m.popups||[]){x.globalAlpha=Math.max(0,pop.life);x.font='bold 26px Outfit, Arial';x.fillStyle=player(ids[pop.owner]).color;x.textAlign='center';x.fillText('+'+pop.points,pop.x,pop.y);}x.globalAlpha=1;
 for(const p of m.particles){x.globalAlpha=Math.max(0,p.life);x.fillStyle=player(ids[p.owner]).color;x.fillRect(p.x,p.y,5,5);}x.globalAlpha=1;
 if(m.chew){x.font='bold 20px Outfit, Arial';x.textAlign='center';x.fillStyle='#ffe3a1';x.fillText(m.chew.stage%2?'CRUNCH!':'NOM!',h.x,h.y-h.h/2-15);}
}

function faceSummary(p){const records=p.results.filter(r=>r.game==='face'),rounds=records.flatMap(r=>r.details.rounds||[r.details]),feeds=records.reduce((s,r)=>s+r.hits,0),shots=rounds.reduce((s,r)=>s+(r.shots||0),0),fastest=Math.min(Infinity,...rounds.map(r=>r.fastestShot??Infinity)),levels=new Set(rounds.filter(r=>r.completed).map(r=>r.level));return `<div class="secret-summary panel"><h3>${esc(p.name)}’s secret records</h3><div><span>Total feeds<b>${feeds}</b></span><span>Highest score<b>${Math.max(0,...records.map(r=>r.score))}</b></span><span>Accuracy<b>${shots?Math.round(100*feeds/shots):0}%</b></span><span>Longest streak<b>${Math.max(0,...rounds.map(r=>r.bestStreak||0))}</b></span><span>Fastest shot<b>${Number.isFinite(fastest)?seconds(fastest):'—'}</b></span><span>Levels completed<b>${levels.size}</b></span><span>Two-player wins<b>${records.filter(r=>r.mode==='versus'&&r.win).length}</b></span></div></div>`;}
